cd /tmp/probe && python3 - <<'EOF'
import sqlite3
def make(path, objs=True):
    c = sqlite3.connect(path)
    if objs:
        c.executescript('''
CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE);
CREATE TABLE posts (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), title TEXT);
CREATE INDEX idx_posts_user ON posts(user_id);
CREATE VIEW user_names AS SELECT id, name FROM users;
CREATE TRIGGER trg AFTER INSERT ON users BEGIN UPDATE users SET name=name WHERE id=new.id; END;
''')
    c.commit(); c.close()
make('full.db')
make('empty.db', objs=False)
make('tables_only.db')
c = sqlite3.connect('tables_only.db')
c.execute("DROP VIEW user_names"); c.execute("DROP TRIGGER trg"); c.execute("DROP INDEX idx_posts_user")
c.commit(); c.close()
EOF
sqlite3 full.db '.schema' 2>/dev/null || python3 -c "import sqlite3; print(sqlite3.connect('full.db').execute(\"select sql from sqlite_master\").fetchall())"
